const assets = {"/academic.css":{"body":":root {\n    --text: #222;\n    --muted: #666;\n    --link: #1772d0;\n    --link-hover: #f09228;\n    --rule: #e5e5e5;\n    --tile: #f4f5f7;\n}\n\n* { box-sizing: border-box; }\n\nhtml { scroll-behavior: smooth; }\n\nbody {\n    margin: 0;\n    background: #fff;\n    color: var(--text);\n    font-family: \"Lato\", Verdana, Helvetica, sans-serif;\n    font-size: 16px;\n    line-height: 1.55;\n    -webkit-font-smoothing: antialiased;\n}\n\na { color: var(--link); text-decoration: none; }\na:hover, a:focus-visible { color: var(--link-hover); text-decoration: underline; }\n\n.page {\n    max-width: 820px;\n    margin: 0 auto;\n    padding: 0 20px 48px;\n}\n\n/* Top bar */\n.topbar {\n    display: flex;\n    flex-wrap: wrap;\n    align-items: baseline;\n    justify-content: space-between;\n    gap: 8px 24px;\n    padding: 22px 0 14px;\n    border-bottom: 1px solid var(--rule);\n}\n\n.topbar .name {\n    color: var(--text);\n    font-size: 1.05rem;\n    font-weight: 700;\n}\n.topbar .name:hover { color: var(--link); text-decoration: none; }\n\n.topbar nav { display: flex; flex-wrap: wrap; gap: 4px 20px; font-size: 0.95rem; }\n\n/* Intro */\n.intro {\n    display: flex;\n    align-items: flex-start;\n    gap: 32px;\n    padding: 36px 0 8px;\n}\n\n.intro-text { flex: 1; min-width: 0; }\n\n.intro h1 {\n    margin: 0 0 14px;\n    font-size: 2.1rem;\n    font-weight: 400;\n    line-height: 1.2;\n}\n\n.intro p { margin: 0 0 12px; }\n\n.photo {\n    flex: none;\n    width: 165px;\n    aspect-ratio: 3 / 4;\n    border-radius: 6px;\n    display: grid;\n    place-items: center;\n    background: var(--tile);\n    border: 1px solid var(--rule);\n    color: #9aa1ab;\n    font-size: 3.4rem;\n    font-weight: 300;\n    letter-spacing: 0.04em;\n    overflow: hidden;\n}\n.photo img { width: 100%; height: 100%; object-fit: cover; object-position: 50% 0; display: block; }\n\n.linkline { color: var(--muted); }\n.linkline a + a::before,\n.linkline a + span::before { content: none; }\n.linkline .sep { margin: 0 6px; color: #bbb; }\n\n/* Sections */\nsection { padding-top: 34px; }\n\nsection > h2 {\n    margin: 0 0 14px;\n    padding-bottom: 6px;\n    border-bottom: 1px solid var(--rule);\n    font-size: 1.4rem;\n    font-weight: 700;\n}\n\n.section-note { margin: -4px 0 18px; color: var(--muted); }\n\n/* Experience / updates lists */\n.entries { margin: 0; padding: 0; list-style: none; }\n\n.entries li {\n    display: grid;\n    grid-template-columns: 96px 1fr;\n    gap: 4px 16px;\n    margin-bottom: 14px;\n}\n\n.entries .when { color: var(--muted); font-size: 0.92rem; white-space: nowrap; }\n\n/* Projects */\n.paper {\n    padding: 16px 0;\n}\n.paper + .paper { border-top: 1px solid var(--rule); }\n.paper > div { min-width: 0; overflow-wrap: anywhere; }\n\n.paper h3 { margin: 0 0 4px; font-size: 1.05rem; font-weight: 700; line-height: 1.35; }\n.paper h3 a { color: var(--link); }\n.paper .tech { margin: 0 0 6px; color: var(--muted); font-style: italic; font-size: 0.95rem; }\n.paper p { margin: 0 0 8px; font-size: 0.97rem; }\n.paper .links { margin: 0; font-size: 0.95rem; }\n.paper .links .sep { margin: 0 5px; color: #bbb; }\n\n/* Skills */\n.skills { margin: 0; display: grid; grid-template-columns: 120px 1fr; gap: 6px 16px; }\n.skills dt { font-weight: 700; }\n.skills dd { margin: 0; }\n\nfooter {\n    margin-top: 44px;\n    padding-top: 16px;\n    border-top: 1px solid var(--rule);\n    color: var(--muted);\n    font-size: 0.88rem;\n    display: flex;\n    flex-wrap: wrap;\n    justify-content: space-between;\n    gap: 6px 20px;\n}\n\n.skip-link {\n    position: absolute;\n    left: -999px;\n    top: 8px;\n    background: #fff;\n    padding: 6px 10px;\n    border: 1px solid var(--rule);\n}\n.skip-link:focus { left: 8px; }\n\n@media (max-width: 640px) {\n    body { font-size: 15.5px; }\n    .intro { flex-direction: column-reverse; align-items: flex-start; gap: 20px; padding-top: 26px; }\n    .photo { width: 120px; }\n    .intro h1 { font-size: 1.75rem; }\n    .entries li { grid-template-columns: 1fr; }\n    .skills { grid-template-columns: 1fr; gap: 0; }\n    .skills dd { margin-bottom: 8px; }\n}\n","type":"text/css; charset=utf-8","encoding":"text"},"/article-book-recommender.html":{"body":"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Query-Based Book Recommender | Shshank Singh</title>\n    \n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n    <link href=\"https://fonts.googleapis.com/css2?family=Lato:ital,wght@0,300;0,400;0,700;1,400&amp;display=swap\" rel=\"stylesheet\">\n    <link rel=\"stylesheet\" href=\"academic.css\">\n    <link rel=\"stylesheet\" href=\"article.css\">\n</head>\n<body class=\"article-page\">\n    <nav class=\"article-nav\">\n        <a class=\"article-brand\" href=\"index.html\"><span class=\"article-brand-mark\">SS</span><span class=\"article-brand-name\">Shshank Singh</span></a>\n        <a class=\"article-back\" href=\"index.html#projects\">← All work</a>\n    </nav>\n    <main class=\"article-shell\">\n        <div class=\"article-header\">\n            <p class=\"article-kicker\">Project 06 / Semantic retrieval</p>\n            <h1 class=\"article-title\">Query-Based Book Recommendation System</h1>\n            <p class=\"article-date\">2025 / Meaning-aware discovery</p>\n        </div>\n        <article class=\"article-content\">\n            <div class=\"article-summary\">\n                <p>A semantic search application that converts natural-language reading intent into ranked books using precomputed description embeddings and cosine similarity.</p>\n                <div class=\"article-facts\">\n                    <div><strong>~5,200 books</strong><span>Clean descriptions</span></div>\n                    <div><strong>384 dimensions</strong><span>MiniLM embeddings</span></div>\n                    <div><strong>1–20 results</strong><span>Configurable Top-K</span></div>\n                </div>\n            </div>\n\n            <h2>Problem and search behaviour</h2>\n            <p>Readers often remember a theme rather than a title: “a mystery in a small town,” “philosophy for someone new to the subject,” or “isolation in deep space.” Keyword search is brittle in this setting because the words in the query may never appear in a book’s description even when the meaning matches.</p>\n            <p>The project treats discovery as semantic retrieval. The query and every book description are encoded with the same sentence model, allowing the system to compare meaning in a shared vector space rather than count overlapping terms.</p>\n\n            <h2>Dataset preparation</h2>\n            <p>The source dataset contains roughly 7,000 records with titles, authors, descriptions, categories, cover URLs, publication years, ratings, and other metadata. Records without usable descriptions are removed, leaving approximately 5,200 entries for retrieval.</p>\n            <p>Embedding generation is deliberately separated from the interactive application. A preparation script loads <code>all-MiniLM-L6-v2</code>, encodes every description with a progress bar, and saves the resulting matrix as <code>book_embeddings.npy</code>. The cleaned dataframe is saved alongside it. This turns a repeated model workload into a one-time indexing step.</p>\n\n            <h2>Retrieval pipeline</h2>\n            <ul>\n                <li><strong>Load:</strong> Streamlit caches the sentence model as a resource and the dataframe/embedding matrix as data.</li>\n                <li><strong>Encode:</strong> only the incoming user query is encoded during interaction.</li>\n                <li><strong>Compare:</strong> scikit-learn computes cosine similarity between the query vector and the complete embedding matrix.</li>\n                <li><strong>Filter:</strong> an optional category filter narrows the candidate dataframe after similarity scores are attached.</li>\n                <li><strong>Rank:</strong> candidates are sorted descending by similarity and truncated to the requested Top-K.</li>\n                <li><strong>Present:</strong> results show cover art, title, author, rating, year, category, score, and an expandable description.</li>\n            </ul>\n\n            <div class=\"article-diagram\" role=\"img\" aria-label=\"Semantic book retrieval pipeline from query through MiniLM embedding and cosine similarity to ranked books\">\n                <div class=\"article-diagram-label\"><span>FIG 01 / RETRIEVAL PIPELINE</span><span>all-MiniLM-L6-v2</span></div>\n                <div class=\"diagram-flow\">\n                    <div><small>QUERY</small><strong>Natural Language</strong><span>user intent</span></div>\n                    <div><small>ENCODER</small><strong>MiniLM</strong><span>384-dimensional vector</span></div>\n                    <div><small>SEARCH</small><strong>Cosine Similarity</strong><span>5.2K descriptions</span></div>\n                    <div><small>RESULT</small><strong>Ranked Books</strong><span>semantic matches</span></div>\n                </div>\n            </div>\n\n            <div class=\"code-sample\">\n                <div class=\"code-sample-header\"><span>app.py / query-time retrieval</span><span>Sentence Transformers</span></div>\n                <pre><code>query_embedding = model.encode([query])\nsimilarities = cosine_similarity(\n    query_embedding,\n    book_embeddings\n)[0]\n\ndf[\"similarity\"] = similarities\ntop_books = filtered_df.sort_values(\n    \"similarity\", ascending=False\n).head(top_k)</code></pre>\n            </div>\n\n            <h2>Why precompute embeddings</h2>\n            <p>Encoding every book description on every interaction would make response time proportional to both corpus size and transformer inference cost. Precomputation changes the query path to one transformer call plus matrix similarity. At this corpus size, brute-force cosine similarity is simple, transparent, and fast enough while preserving exact ranking.</p>\n            <p>The trade-off is index freshness. When descriptions change or books are added, the embedding file must be regenerated. A larger or frequently changing catalogue would benefit from a vector database, incremental indexing, and versioned embeddings.</p>\n\n            <h2>Interface decisions</h2>\n            <p>The sidebar exposes Top-K and a curated category filter. Results are presented as metadata-rich rows rather than only a list of titles. Displaying the similarity score is useful for debugging and demonstration, although a consumer-facing product might hide it or translate it into a less technical relevance explanation.</p>\n            <p>Cover images are loaded from dataset URLs, while missing covers fall back to a placeholder. Descriptions are collapsed by default so the user can scan multiple recommendations without facing a wall of text.</p>\n\n            <h2>Evaluation and limitations</h2>\n            <p>Cosine similarity provides a ranking but does not establish that the recommendations are useful. A robust evaluation set would pair realistic queries with human relevance labels and report Precision@K, Recall@K, NDCG, and qualitative failure categories.</p>\n            <p>The model only sees descriptions, so it may miss signals contained in reviews, series information, audience, writing style, or reader behaviour. Category filtering is implemented as substring matching, which is convenient but not a formal taxonomy. The project is semantic search rather than collaborative recommendation, and the article uses that distinction deliberately.</p>\n\n            <div class=\"article-callout\">\n                <strong>Most important lesson</strong>\n                <p>For small corpora, the simplest retrieval architecture can be the best one. Precomputed embeddings plus exact cosine similarity made the system easy to inspect, test, and explain before introducing approximate indexes.</p>\n            </div>\n\n            <h2>Next steps</h2>\n            <p>A stronger version would add a labelled query set, hybrid lexical/vector retrieval, diversity-aware reranking, query history, embedding-version checks, and filters driven by normalized metadata. Moving the matrix into Qdrant or another ANN service would become valuable once corpus size or update frequency justifies the added operational complexity.</p>\n\n            <div class=\"article-links\">\n                <a href=\"https://query-based-book-recommender-system.streamlit.app\" target=\"_blank\" rel=\"noreferrer\">Open live application ↗</a>\n                <a href=\"https://github.com/levithion/Query-Based-Book-Recommender-System-Using-Sentence-Transformers\" target=\"_blank\" rel=\"noreferrer\">Browse source code ↗</a>\n            </div>\n            \n            <a href=\"index.html#projects\" class=\"back-link\">Return to portfolio <span>→</span></a>\n        </article>\n    </main>\n    <footer class=\"article-footer\"><span>© 2026 Shshank Singh</span><span>Project documentation</span></footer>\n</body>\n</html>\n","type":"text/html; charset=utf-8","encoding":"text"},"/article-drowsiness.html":{"body":"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Driver Drowsiness Detection System | Shshank Singh</title>\n    \n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n    <link href=\"https://fonts.googleapis.com/css2?family=Lato:ital,wght@0,300;0,400;0,700;1,400&amp;display=swap\" rel=\"stylesheet\">\n    <link rel=\"stylesheet\" href=\"academic.css\">\n    <link rel=\"stylesheet\" href=\"article.css\">\n</head>\n<body class=\"article-page\">\n    <nav class=\"article-nav\">\n        <a class=\"article-brand\" href=\"index.html\"><span class=\"article-brand-mark\">SS</span><span class=\"article-brand-name\">Shshank Singh</span></a>\n        <a class=\"article-back\" href=\"index.html#projects\">← All work</a>\n    </nav>\n    <main class=\"article-shell\">\n        <div class=\"article-header\">\n            <p class=\"article-kicker\">Project 05 / Computer vision</p>\n            <h1 class=\"article-title\">Driver Drowsiness Detection System</h1>\n            <p class=\"article-date\">Jan 2025 — Apr 2025</p>\n        </div>\n        <article class=\"article-content\">\n            <div class=\"article-summary\">\n                <p>A browser-based drowsiness classifier supporting uploaded images, sampled video analysis, and a live WebRTC camera pipeline with temporal smoothing and audible warnings.</p>\n                <div class=\"article-facts\">\n                    <div><strong>41,793 images</strong><span>Training dataset reported</span></div>\n                    <div><strong>224 × 224</strong><span>Model input</span></div>\n                    <div><strong>3-frame window</strong><span>Live score smoothing</span></div>\n                </div>\n            </div>\n\n            <h2>Problem and product boundary</h2>\n            <p>A frame-level eye classifier is not automatically a drowsiness-detection product. The application must obtain camera data, locate a useful facial region, normalize it for the model, smooth unstable predictions, surface confidence, and create a warning that a driver can notice.</p>\n            <p>This project explores that complete loop. It is an educational prototype rather than a certified safety device, but it deliberately includes the system components surrounding the classifier instead of presenting only a training notebook.</p>\n\n            <h2>Model and preprocessing</h2>\n            <p>The repository uses a Keras classifier based on a MobileNetV2 transfer-learning backbone with custom dense layers for binary classification between <em>Drowsy</em> and <em>Alert</em>. MobileNetV2 was chosen because depthwise separable convolutions provide a favourable compute–accuracy trade-off for interactive inference.</p>\n            <ul>\n                <li><strong>Face detection:</strong> an OpenCV Haar cascade searches the equalized grayscale frame and selects the largest detected face.</li>\n                <li><strong>Eye-region focus:</strong> a second cascade looks for up to two large eye regions. If eyes are not found, the pipeline falls back to the upper portion of the face; if no face is found, it uses the full frame.</li>\n                <li><strong>Normalization:</strong> the chosen crop is converted to RGB, resized to 224 × 224, scaled to the 0–1 range, and expanded into a model batch.</li>\n                <li><strong>Output interpretation:</strong> both scalar sigmoid and two-score model outputs are supported, making the serving utility tolerant of alternative exported heads.</li>\n            </ul>\n\n            <div class=\"article-diagram model-architecture\" role=\"img\" aria-label=\"Complete drowsiness inference flow from camera frame through MobileNetV2 to a temporally smoothed driver alert\">\n                <div class=\"article-diagram-label\"><span>FIG 01 / INFERENCE ARCHITECTURE</span><span>MobileNetV2 · edge-oriented pipeline</span></div>\n                <div class=\"model-flow\">\n                    <div><small>01 / INPUT</small><strong>Camera Frame</strong><span>BGR video stream</span></div>\n                    <div><small>02 / ROI</small><strong>Face + Eyes</strong><span>Haar cascade crop</span></div>\n                    <div><small>03 / PREP</small><strong>Normalize</strong><span>RGB · 224 × 224</span></div>\n                    <div class=\"model-stage\"><small>04 / MODEL</small><strong>MobileNetV2</strong><span>feature backbone</span></div>\n                    <div><small>05 / HEAD</small><strong>Binary Classifier</strong><span>alert / drowsy</span></div>\n                    <div class=\"output-stage\"><small>06 / OUTPUT</small><strong>Temporal Alert</strong><span>smoothed confidence</span></div>\n                </div>\n                <div class=\"model-readout\"><span>INPUT / 224 × 224 × 3</span><span>BACKBONE / DEPTHWISE SEPARABLE CNN</span><span>OUTPUT / CLASS + CONFIDENCE</span></div>\n            </div>\n\n            <h2>Three inference modes</h2>\n            <h3>Uploaded image</h3>\n            <p>The simplest path runs the full preprocessing and prediction pipeline once, returning the class and confidence. This is useful for checking model behaviour and debugging crop selection.</p>\n            <h3>Uploaded video</h3>\n            <p>The video analyzer samples every fifteenth frame, processes at most 120 frames, and aggregates the frame classifications with a majority decision. Sampling controls processing cost and makes the hosted application usable without decoding and inferring on every frame.</p>\n            <h3>Live camera</h3>\n            <p><code>streamlit-webrtc</code> obtains frames inside the browser. The processor infers every eighth frame, keeps deques of the three most recent alert and drowsy scores, and compares their rolling averages. That short window reduces the chance that a blink or one poor crop flips the interface state.</p>\n\n            <div class=\"code-sample\">\n                <div class=\"code-sample-header\"><span>app.py / temporal smoothing</span><span>Live WebRTC</span></div>\n                <pre><code>if frame_count % 8 == 0:\n    scores = predict_frame(image)[\"scores\"]\n    recent_alert.append(scores[\"alert\"])\n    recent_drowsy.append(scores[\"drowsy\"])\n\n    alert = sum(recent_alert) / len(recent_alert)\n    drowsy = sum(recent_drowsy) / len(recent_drowsy)\n    prediction = \"Drowsy\" if drowsy &gt; alert else \"Alert\"</code></pre>\n            </div>\n\n            <h2>User feedback and warning path</h2>\n            <p>The interface shows the active crop mode, prediction, and confidence. When the smoothed state becomes drowsy, it renders a prominent warning and plays a generated 800 Hz audio tone. The tone is embedded as base64 audio so it survives Streamlit’s periodic refresh cycle without depending on a separate media file.</p>\n\n            <h2>Evaluation and caveats</h2>\n            <p>The repository reports 99.99% training accuracy and 100% test accuracy on its train/test split. Those values should be interpreted cautiously: a safety-relevant vision system also needs subject-independent splits, varied camera positions, difficult lighting, glasses and occlusions, demographic coverage, and field testing. Accuracy on a curated image dataset does not prove road readiness.</p>\n            <p>Haar cascades are lightweight but fragile under extreme pose and lighting. The live hosted demo can also experience limited frame rate because WebRTC plus neural inference competes for free-tier compute. These limitations are stated explicitly rather than hidden behind a single accuracy number.</p>\n\n            <div class=\"article-callout\">\n                <strong>Next engineering step</strong>\n                <p>Benchmark the full pipeline—not only the CNN—across capture latency, face-detection success, inference time, alert delay, false alarms during normal blinking, and performance by environment.</p>\n            </div>\n\n            <h2>What the project demonstrated</h2>\n            <p>The central lesson was that temporal and interface design can be as important as the image model. Crop fallbacks, sampling policy, rolling averages, WebRTC behaviour, and warning delivery determine whether a classifier becomes a coherent real-time application.</p>\n\n            <div class=\"article-links\">\n                <a href=\"https://driver-drowsiness-detection-system.streamlit.app\" target=\"_blank\" rel=\"noreferrer\">Open live application ↗</a>\n                <a href=\"https://github.com/levithion/Driver-Drowsiness-Detection\" target=\"_blank\" rel=\"noreferrer\">Browse source code ↗</a>\n            </div>\n            \n            <a href=\"index.html#projects\" class=\"back-link\">Return to portfolio <span>→</span></a>\n        </article>\n    </main>\n    <footer class=\"article-footer\"><span>© 2026 Shshank Singh</span><span>Project documentation</span></footer>\n</body>\n</html>\n","type":"text/html; charset=utf-8","encoding":"text"},"/article-huffman.html":{"body":"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Context-Aware Huffman Compressor | Shshank Singh</title>\n    \n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n    <link href=\"https://fonts.googleapis.com/css2?family=Lato:ital,wght@0,300;0,400;0,700;1,400&amp;display=swap\" rel=\"stylesheet\">\n    <link rel=\"stylesheet\" href=\"academic.css\">\n    <link rel=\"stylesheet\" href=\"article.css\">\n</head>\n<body class=\"article-page\">\n    <nav class=\"article-nav\">\n        <a class=\"article-brand\" href=\"index.html\"><span class=\"article-brand-mark\">SS</span><span class=\"article-brand-name\">Shshank Singh</span></a>\n        <a class=\"article-back\" href=\"index.html#projects\">← All work</a>\n    </nav>\n    <main class=\"article-shell\">\n        <div class=\"article-header\">\n            <p class=\"article-kicker\">Project 04 / Information theory</p>\n            <h1 class=\"article-title\">Context-Aware Huffman Compressor</h1>\n            <p class=\"article-date\">Aug 2025 — Dec 2025</p>\n        </div>\n        <article class=\"article-content\">\n            <div class=\"article-summary\">\n                <p>A lossless compressor that replaces one global Huffman codebook with deterministic, context-conditioned trees and a safe escape path for unseen transitions.</p>\n                <div class=\"article-facts\">\n                    <div><strong>Word or character</strong><span>Tokenization modes</span></div>\n                    <div><strong>N-order</strong><span>Configurable context</span></div>\n                    <div><strong>CLI + Streamlit</strong><span>Two product surfaces</span></div>\n                </div>\n            </div>\n\n            <h2>Why context matters</h2>\n            <p>Standard Huffman coding assigns a variable-length code using global symbol frequencies. It is optimal among prefix codes for that one memoryless distribution, but text is not memoryless. After “q,” the probability of “u” is much higher than its probability across the document; whitespace, punctuation, source code, and repeated phrases all have similarly strong local structure.</p>\n            <p>The project asks whether a codebook conditioned on the previous N tokens can move the practical bit rate closer to conditional entropy. Instead of changing Huffman’s tree construction, it changes the distribution supplied to the tree.</p>\n\n            <h2>Compression pipeline</h2>\n            <p>The canonical implementation supports word-level tokenization that preserves whitespace exactly and character-level tokenization for lower-level analysis. It first builds a global frequency map, then a separate frequency map for every observed context tuple.</p>\n            <ul>\n                <li><strong>Deterministic trees:</strong> ties are broken using symbol values so the decoder can reconstruct exactly the same trees from serialized frequency maps.</li>\n                <li><strong>Context selection:</strong> the previous N tokens select the active codebook for the next symbol.</li>\n                <li><strong>Escape fallback:</strong> when a context has not observed every global token, an <code>&lt;ESC&gt;</code> symbol signals the decoder to read the next symbol from the global tree.</li>\n                <li><strong>Bit packing:</strong> a custom writer packs individual prefix-code bits into bytes instead of storing strings of zeros and ones.</li>\n                <li><strong>Self-contained output:</strong> a four-byte header length, JSON metadata, and raw bitstream allow independent decompression.</li>\n            </ul>\n\n            <figure class=\"article-figure\">\n                <img src=\"assets/projects/huffman-pipeline.png\" alt=\"Context-aware Huffman compression pipeline from text input through context analysis and tree generation to compressed output\">\n                <figcaption><span>FIG 01 / COMPRESSION PIPELINE</span><span>Context changes the codebook selected for each token</span></figcaption>\n            </figure>\n\n            <h2>The escape-path problem</h2>\n            <p>A context codebook only knows tokens observed after that context in the training text. If the encoder later sees an unseen transition, the decoder needs an unambiguous way to fall back. The implementation inserts a unique escape token into context trees whose vocabulary is a strict subset of the global vocabulary. It does not insert the token when the context already covers everything, because doing so would lengthen codes for a branch that can never be used.</p>\n\n            <div class=\"code-sample\">\n                <div class=\"code-sample-header\"><span>main.py / context fallback rule</span><span>Lossless coding</span></div>\n                <pre><code>def needs_escape(context_vocab, global_vocab):\n    return context_vocab &lt; global_vocab\n\nif token in context_codes:\n    writer.write_bits(context_codes[token])\nelse:\n    writer.write_bits(context_codes[escape_token])\n    writer.write_bits(global_codes[token])</code></pre>\n            </div>\n\n            <h2>Decoding and correctness</h2>\n            <p>Decompression reads the header, reconstructs the deterministic global and context trees, and then walks one tree per output token. A fixed-length deque maintains the same context state as the encoder. When the decoder reaches an escape leaf, it switches to the global tree for exactly one token before updating the context window.</p>\n            <p>Because word mode preserves whitespace tokens and the output records the total token count, decompression can reconstruct the original text without inserting or normalizing spaces. That round-trip property is more important than a favourable benchmark: a compressor that cannot reproduce input bytes is not useful.</p>\n\n            <h2>Measurement</h2>\n            <p>The experiment harness compares original byte size, regular Huffman size, context-aware size, compression ratios, encoding throughput, global Shannon entropy, conditional entropy, and actual bits per token. It also reports high-frequency contexts where the conditional codebook saves the most bits relative to the global codebook.</p>\n            <p>The repository’s generated charts show that gains depend heavily on the data distribution. Repetitive text and code-like patterns create strong contexts; heterogeneous or small corpora provide less predictable benefit because the metadata and extra trees carry overhead.</p>\n\n            <figure class=\"article-figure\">\n                <img src=\"assets/projects/huffman-compression.png\" alt=\"Benchmark chart comparing compression ratios for regular and context-aware Huffman coding\">\n                <figcaption><span>FIG 02 / BENCHMARK</span><span>Context-aware coding leads across every tested data shape</span></figcaption>\n            </figure>\n\n            <h2>Trade-offs</h2>\n            <p>The main cost is state explosion. As order increases, the number of possible contexts and trees can grow rapidly, increasing header size and memory consumption. A higher-order model is therefore not automatically better. Practical deployment would need context pruning, minimum-frequency thresholds, compact binary metadata, and selection of order based on total file size rather than bitstream size alone.</p>\n\n            <div class=\"article-callout\">\n                <strong>What this project taught me</strong>\n                <p>The theoretical improvement from conditional distributions only matters after accounting for the cost of communicating the model. Compression is a systems problem involving algorithms, serialization, determinism, memory, and measurement.</p>\n            </div>\n\n            <h2>Product surfaces</h2>\n            <p>The CLI supports compressing, decompressing, and running built-in experiments. The Streamlit application exposes the same mechanism interactively with text/file input, configurable tokenization and context order, entropy metrics, and analytical charts. Keeping both surfaces tied to the same canonical logic reduces the risk that a demonstration diverges from the actual file format.</p>\n\n            <div class=\"article-links\">\n                <a href=\"https://context-aware-huffman.streamlit.app\" target=\"_blank\" rel=\"noreferrer\">Open live application ↗</a>\n                <a href=\"https://github.com/levithion/Context-Aware-Huffman\" target=\"_blank\" rel=\"noreferrer\">Browse source code ↗</a>\n            </div>\n            \n            <a href=\"index.html#projects\" class=\"back-link\">Return to portfolio <span>→</span></a>\n        </article>\n    </main>\n    <footer class=\"article-footer\"><span>© 2026 Shshank Singh</span><span>Project documentation</span></footer>\n</body>\n</html>\n","type":"text/html; charset=utf-8","encoding":"text"},"/article-lumina.html":{"body":"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Lumina Private Memory Search | Shshank Singh</title>\n    \n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n    <link href=\"https://fonts.googleapis.com/css2?family=Lato:ital,wght@0,300;0,400;0,700;1,400&amp;display=swap\" rel=\"stylesheet\">\n    <link rel=\"stylesheet\" href=\"academic.css\">\n    <link rel=\"stylesheet\" href=\"article.css\">\n</head>\n<body class=\"article-page\">\n    <nav class=\"article-nav\">\n        <a class=\"article-brand\" href=\"index.html\"><span class=\"article-brand-mark\">SS</span><span class=\"article-brand-name\">Shshank Singh</span></a>\n        <a class=\"article-back\" href=\"index.html#projects\">← All work</a>\n    </nav>\n    <main class=\"article-shell\">\n        <div class=\"article-header\">\n            <p class=\"article-kicker\">Project 02 / Multimodal retrieval</p>\n            <h1 class=\"article-title\">Lumina Local-First Multimodal Memory Search Engine</h1>\n            <p class=\"article-date\">Jul 2026 — Aug 2026</p>\n        </div>\n        <article class=\"article-content\">\n            <div class=\"article-summary\">\n                <p>Lumina indexes your screenshots and photos entirely on-device, captions each one with a local vision-language model, and makes the whole library searchable by meaning, on-screen text, and time. Nothing ever leaves the machine.</p>\n                <div class=\"article-facts\">\n                    <div><strong>3 fused signals</strong><span>Visual · semantic · exact text</span></div>\n                    <div><strong>~10 seconds</strong><span>New screenshot to searchable</span></div>\n                    <div><strong>Zero cloud</strong><span>Local models, embedded Qdrant, localhost-only API</span></div>\n                </div>\n            </div>\n\n            <h2>Problem and objective</h2>\n            <p>A few months of normal computer use produces thousands of files named “Screenshot 2026-08-12 at 10.34.17.png”. The information needed to find one again — which app it showed, what the error message said, roughly when it happened — exists only inside the pixels. Filename search cannot help, and shipping a personal screen history to a cloud vision API is not an acceptable trade for convenience.</p>\n            <p>The objective became: type what you remember — “the terminal error about permissions last week”, “that hotel listing with a brick wall” — and get the image back, under a hard constraint that every caption, embedding, and byte of data stays on the machine.</p>\n\n            <h2>From cloud demo to local-first product</h2>\n            <p>The first version of Lumina looked conventional: it encoded a fixed collection of 8,092 images with CLIP, stored vectors in hosted Qdrant, and served results through FastAPI and Streamlit. Operating that deployment surfaced recurring failures — payloads referencing files missing from the serving container, credentials committed to public source, scheduled sync jobs failing silently for days. Each incident demanded a redesign rather than a patch.</p>\n            <p>The current Lumina inverts the topology. Instead of moving images toward a cloud index, it moves the index to the images: an embedded Qdrant store, on-device models, and a localhost server wrapped in a native window. Privacy stopped being a promise in a README and became an architectural property.</p>\n\n            <h2>System architecture</h2>\n            <p>Embedded Qdrant allows exactly one process per data directory, and that constraint shaped everything else. Rather than fight it with locks and IPC, Lumina embraces it: <code>main.py</code> hosts the FastAPI server, both encoder models, the filesystem watcher, and the database in a single OS process. Launching a second instance fails fast with human guidance (<code>lsof qdrant_data/.lock</code>, or point <code>MEMORY_STORAGE_PATH</code> elsewhere) instead of corrupting the store.</p>\n            <ul>\n                <li><strong>Ingestion:</strong> discovers JPEG, PNG, and HEIC files, extracts EXIF/mtime capture dates, runs SmolVLM captioning plus optional Tesseract OCR, computes dual embeddings, and upserts points in batches of 32.</li>\n                <li><strong>Storage:</strong> embedded Qdrant holds two named vector spaces per point — a 512-dimensional CLIP visual vector and a 384-dimensional MiniLM vector over <code>caption + OCR + tags</code> — alongside payload indexes for datetime, keyword, and full-text fields.</li>\n                <li><strong>Retrieval:</strong> hybrid search fuses visual similarity, semantic similarity, and exact token overlap, with safety and date-range filters pushed into Qdrant before top-K truncation.</li>\n                <li><strong>Interface:</strong> a pywebview native window over static UI assets, served by FastAPI bound to <code>127.0.0.1:8337</code>. Headless <code>--web</code> mode and a launchd plist run the same engine without a window.</li>\n            </ul>\n\n            <div class=\"article-diagram\" role=\"img\" aria-label=\"Lumina system flow from the local screenshots folder through VLM and OCR ingestion into an embedded Qdrant store, queried by a pywebview window over a localhost FastAPI server\">\n                <div class=\"article-diagram-label\"><span>FIG 01 / SINGLE-PROCESS ARCHITECTURE</span><span>Models, watcher, API, and database in one process</span></div>\n                <div class=\"diagram-flow\">\n                    <div><small>SOURCE</small><strong>~/Screenshots</strong><span>screenshots · photos · HEIC</span></div>\n                    <div><small>INGESTION</small><strong>SmolVLM + OCR</strong><span>dedup · repair · sweep</span></div>\n                    <div><small>STORAGE</small><strong>Embedded Qdrant</strong><span>dual vectors · payload indexes</span></div>\n                    <div><small>INTERFACE</small><strong>pywebview window</strong><span>FastAPI on 127.0.0.1</span></div>\n                </div>\n            </div>\n\n            <h2>Why three signals beat one</h2>\n            <p>Raw CLIP similarity alone is weak for this domain: screenshots of the same app look nearly identical visually, so a query about a specific error returns every terminal window ever captured. Lumina therefore scores each result from three complementary signals. A MiniLM embedding of the caption-plus-OCR document carries meaning, an exact term-overlap score anchors literal matches (“permissions” must literally appear), and the CLIP visual vector still finds images no text describes well.</p>\n            <p>The default memory profile weights these at 10% visual, 50% semantic, 40% exact. Candidate generation pulls <code>max(limit × 4, 40)</code> hits from each vector space independently, merges them by point ID, then reranks the union — so a result that only one source discovered can still win after fusion.</p>\n\n            <div class=\"code-sample\">\n                <div class=\"code-sample-header\"><span>retrieval.py / hybrid fusion</span><span>Dual-vector Qdrant queries</span></div>\n                <pre><code>common = {\"collection_name\": collection_name,\n          \"limit\": max(limit * 4, 40),\n          \"query_filter\": build_search_filter(\n              safe_only=safe, date_from=date_from, date_to=date_to)}\nsources = {\n    \"visual\":   client.query_points(query=visual_vector,\n                                    using=\"visual\", **common).points,\n    \"semantic\": client.query_points(query=text_vector,\n                                    using=\"semantic_text\", **common).points,\n}\n# merge hits by point ID, keep each channel's best score, then:\nscore = (w_visual * best_visual\n         + w_semantic * best_semantic\n         + w_exact * _text_score(query, payload))</code></pre>\n            </div>\n\n            <h2>Queries that understand time</h2>\n            <p>Memory requests are saturated with temporal language, so the server parses it before embedding anything. A stdlib-only parser recognizes phrases like “yesterday”, “last week”, “in March”, and “since June”, strips them from the query, and resolves them against the current clock into concrete UTC bounds. The remaining text becomes the embedding; the bounds become a <code>DatetimeRange</code> filter on the indexed <code>created_at</code> field.</p>\n            <p>Evaluating that filter inside Qdrant matters for correctness, not just speed: it constrains the candidate pool before top-K truncation, so a match from six months ago cannot be crowded out by forty fresher near-misses. Only one date phrase per query is interpreted — combining “last week in March” stays deliberately ambiguous instead of silently wrong.</p>\n\n            <h2>An ingestion pass that respects your time</h2>\n            <p>The first full-library scan is genuinely expensive because SmolVLM captions every new file. Everything after it is engineered to be nearly free. A stat-signature cache (size plus nanosecond mtime) identifies unchanged files without re-hashing or touching the database. Files that did change are hashed once with SHA-256; that digest becomes the point’s deterministic UUID, which makes identity content-addressed rather than path-based.</p>\n            <p>That choice pays off repeatedly. A file moved to a new folder is repaired in place with a payload update instead of being re-captioned. An edited screenshot indexes as its own new point while an hourly-throttled sweep deletes the superseded one. Failed files keep their failure status and retry automatically on the next scan, so transient errors never strand items permanently.</p>\n\n            <h2>Live indexing</h2>\n            <p>A watchdog observer over macOS FSEvents feeds a trailing-edge debouncer: saving one screenshot fires a burst of events, but the scan triggers exactly once, ten seconds after activity settles. Because <code>scan_library</code> is idempotent, timer-thread re-entry is safe, and a failed watch cycle logs a warning and waits for the next change rather than killing the thread. New screenshots become searchable roughly ten seconds after capture, with no manual action.</p>\n\n            <h2>Reverse image search and duplicate detection</h2>\n            <p>Any image can be posted to the API as a probe. Lumina embeds it with CLIP for neighbor search and hashes it with a perceptual hash for copy detection; Hamming distance zero marks an exact repost and distance up to eight marks a near-duplicate. Duplicate tiers are promoted above plain visual neighbors during ranking, so when you ask “where did I see this?”, the original outranks everything similar to it.</p>\n\n            <div class=\"article-callout\">\n                <strong>Loud failure beats silent success</strong>\n                <p>Silent degradation was the recurring enemy across versions: captioning failures produced empty captions nobody noticed, sync jobs skipped uploads without error, and an unreachable database was indistinguishable from a missing collection. Every one of those paths now fails loudly — a disabled captioner prints why, storage conflicts exit with instructions, and health status exposes counts, watcher state, and last-scan failures.</p>\n            </div>\n\n            <h2>Privacy and security posture</h2>\n            <p>The privacy model is enforced by construction. Embeddings, captions, and OCR run locally; the server binds to loopback only; and uninstalling means deleting the project folder. File-serving endpoints verify that a requested absolute path actually exists in the index before touching the filesystem, returning 404 otherwise — nothing outside the library is reachable through the API. The SmolVLM safe-content verdict is stored as an <code>is_sensitive</code> payload field and enforced as a database-level <code>must_not</code> filter, which also keeps legacy points lacking that field visible rather than silently hidden.</p>\n\n            <h2>Testing and CI</h2>\n            <p>The app factory accepts injected encoder and client objects, so the test suite stubs the model layer entirely. CI installs only lightweight dependencies — no multi-gigabyte torch download — and covers ingestion cache behavior, dedup and move repair, sweep correctness, hybrid ranking math, date-phrase parsing, and every API endpoint including the indexed-path security checks.</p>\n\n            <h2>Trade-offs and limitations</h2>\n            <p>The design is macOS-first: Finder reveal via <code>open -R</code> and the launchd integration assume a Mac, though the retrieval engine itself is portable Python. First-run indexing is slow while SmolVLM captions the backlog; <code>CAPTION_ENABLED=0</code> trades caption recall for a fast OCR-and-visual-only pass. Tesseract remains optional, but its absence measurably hurts recall on text-heavy screenshots. Finally, the safe-content filter is a small-model heuristic — helpful, not a guarantee.</p>\n\n            <h2>Outcome and next steps</h2>\n            <p>Lumina now closes the loop it originally proved — encode, store, search, serve — but on terms a personal archive actually requires: incremental freshness, honest failure modes, and privacy by architecture. Planned next steps include a relevance-judged evaluation set for tuning fusion weights, latency percentile tracking behind the status endpoint, quantized ONNX encoders for faster cold starts, and portable replacements for the macOS-specific reveal and autostart layers.</p>\n\n            <div class=\"article-links\">\n                <a href=\"https://github.com/levithion/Lumina\" target=\"_blank\" rel=\"noreferrer\">Browse source code ↗</a>\n            </div>\n            \n            <a href=\"index.html#projects\" class=\"back-link\">Return to portfolio <span>→</span></a>\n        </article>\n    </main>\n    <footer class=\"article-footer\"><span>© 2026 Shshank Singh</span><span>Project documentation</span></footer>\n</body>\n</html>\n","type":"text/html; charset=utf-8","encoding":"text"},"/article-ncf-recommender.html":{"body":"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Neural Collaborative Filtering Movie Recommender | Shshank Singh</title>\n    \n    <!-- Google Fonts -->\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n    <link href=\"https://fonts.googleapis.com/css2?family=Lato:ital,wght@0,300;0,400;0,700;1,400&amp;display=swap\" rel=\"stylesheet\">\n    <link rel=\"stylesheet\" href=\"academic.css\">\n    <link rel=\"stylesheet\" href=\"article.css\">\n</head>\n<body class=\"article-page\">\n    <nav class=\"article-nav\">\n        <a class=\"article-brand\" href=\"index.html\"><span class=\"article-brand-mark\">SS</span><span class=\"article-brand-name\">Shshank Singh</span></a>\n        <a class=\"article-back\" href=\"index.html#projects\">← All work</a>\n    </nav>\n    <main class=\"article-shell\">\n        <div class=\"article-header\">\n            <p class=\"article-kicker\">Project 03 / Personalization</p>\n            <h1 class=\"article-title\">Neural Collaborative Filtering Movie Recommender</h1>\n            <p class=\"article-date\">May 2025 — Jul 2025</p>\n        </div>\n        <article class=\"article-content\">\n            <div class=\"article-summary\">\n                <p>CineMatch is a personalized movie-discovery product built around a PyTorch NCF model, a hybrid recommendation engine, a FastAPI service, a Streamlit client, and persistent user taste data.</p>\n                <div class=\"article-facts\">\n                    <div><strong>100K ratings</strong><span>MovieLens interactions</span></div>\n                    <div><strong>Hybrid</strong><span>NCF + content + popularity</span></div>\n                    <div><strong>0.5–5.0</strong><span>User rating range</span></div>\n                </div>\n            </div>\n\n            <h2>From model to product</h2>\n            <p>A recommender must estimate preference from sparse observations, but a useful product also needs accounts, a catalogue, search, metadata, persistence, and a way to handle movies that have never appeared in the training data. CineMatch extends the original NCF project into that complete discovery loop: users sign up, rate films, browse or search for titles, and receive recommendations tailored to their taste.</p>\n            <p>The initial MovieLens small dataset contributes roughly 100,000 ratings across 600 users and approximately 9,000 movies. The repository also supports IMDb-linked OMDb search, allowing a user to import a title outside the original catalogue and keep it in a local CineMatch library.</p>\n\n            <h2>Model architecture</h2>\n            <p>The collaborative component implements an <code>ItemBasedNCF</code> model in PyTorch. User and movie IDs are mapped to separate 64-dimensional embeddings, concatenated into a 128-dimensional vector, and processed by a multilayer perceptron. The network uses 128, 64, and 32 hidden units with ReLU, batch normalization, and 0.3 dropout, then adds learned user, movie, and global biases. Its output is clamped to the valid 0.5–5.0 rating range.</p>\n            <ul>\n                <li><strong>Learned representations:</strong> independent embedding tables capture latent factors for users and movies.</li>\n                <li><strong>Non-linear interaction:</strong> dense layers of 128, 64, and 32 units use ReLU activations, batch normalization, and 0.3 dropout.</li>\n                <li><strong>Bias correction:</strong> learned user, movie, and global bias terms capture systematic rating tendencies outside the interaction network.</li>\n                <li><strong>Bounded output:</strong> the final estimate is clamped to the valid 0.5–5.0 rating range.</li>\n            </ul>\n\n            <div class=\"article-diagram\" role=\"img\" aria-label=\"Neural collaborative filtering architecture from user and movie identifiers through embeddings and an MLP to a predicted rating\">\n                <div class=\"article-diagram-label\"><span>FIG 01 / ITEM-BASED NCF GRAPH</span><span>PyTorch inference</span></div>\n                <div class=\"diagram-flow\">\n                    <div><small>INPUT</small><strong>User + Movie IDs</strong><span>integer tensors</span></div>\n                    <div><small>REPRESENTATION</small><strong>64D + 64D</strong><span>latent embeddings</span></div>\n                    <div><small>INTERACTION</small><strong>128 → 64 → 32</strong><span>MLP + normalization</span></div>\n                    <div><small>OUTPUT</small><strong>Predicted Rating</strong><span>network + learned biases</span></div>\n                </div>\n            </div>\n\n            <h2>Hybrid recommendation generation</h2>\n            <p>At startup, the backend rebuilds stable mappings between MovieLens identifiers and contiguous embedding indices, loads <code>final_model.pth</code> onto MPS, CUDA, or CPU, and prepares a TF-IDF matrix from each title and its genres. The API also computes catalogue popularity from rating counts and community averages.</p>\n            <p>When a user requests recommendations, the service builds a taste profile from their saved ratings and genres. Known movies receive a blended score from the NCF signal, content similarity, and popularity. Imported movies without learned embeddings follow a cold-start path based on content similarity and popularity. Already-rated movies are removed before the final list is sorted and returned.</p>\n\n            <div class=\"code-sample\">\n                <div class=\"code-sample-header\"><span>model_handler.py / ranking loop</span><span>PyTorch</span></div>\n                <pre><code>known_score = (\n    ncf_signal * 0.55\n    + content_similarity * 0.30\n    + popularity * 0.15\n)\ncold_start_score = content_similarity * 0.75 + popularity * 0.25\n\ncandidates = remove_rated_movies(candidates, user_id)\nrecommendations = rank_and_take_top_k(candidates, top_k)</code></pre>\n            </div>\n\n            <h2>Application architecture</h2>\n            <p>The FastAPI layer owns model inference, hybrid ranking, catalog search, authentication, rating writes, watchlists, similar-movie queries, and OMDb integration. SQLite stores accounts, ratings, watchlists, and imported catalogue records. Pydantic request models constrain inputs such as ratings and Top-K values, while the model handler enriches responses with titles, genres, years, community ratings, and optional posters.</p>\n            <p>The Streamlit application consumes the API rather than loading the model directly. The resulting flow is a small but complete product: sign in, rate at least a few films, receive a “Picked for you” list, discover or import more titles, save a watchlist, and inspect the profile’s rating history.</p>\n\n            <div class=\"article-callout\">\n                <strong>Engineering trade-off</strong>\n                <p>The NCF checkpoint is not retrained after every rating. New ratings are persisted immediately and shape the user’s content-based taste profile, while scheduled retraining can refresh collaborative signals later. This keeps the interactive app responsive without pretending that a static checkpoint has learned a new embedding instantly.</p>\n            </div>\n\n            <h2>Evaluation and limitations</h2>\n            <p>Offline quality should be measured with a held-out interaction split using metrics aligned to the product goal—for example RMSE for rating estimation and Hit Rate or NDCG for Top-K ranking. The repository documents the serving path but does not publish benchmark values, so the portfolio avoids inventing them.</p>\n            <p>New users still need to rate a few films before recommendations unlock, and the NCF checkpoint remains fixed between retraining runs. The local SQLite store is appropriate for a demo but needs a persistent disk or managed database in production. Candidate scoring is also intentionally simple and would benefit from batching and model-version metadata at larger scale.</p>\n\n            <h2>What the project demonstrated</h2>\n            <p>This project connected model training with the less glamorous work that makes recommendations usable: identifier mapping, hybrid scoring, cold-start handling, authentication, persistence, metadata enrichment, API contracts, and a focused interface. The result is not only a neural network that predicts ratings, but a product that gives those predictions a practical place to live.</p>\n\n            <div class=\"article-links\">\n                <a href=\"https://ncf-based-movie-recommender-system.streamlit.app\" target=\"_blank\" rel=\"noreferrer\">Open live application ↗</a>\n                <a href=\"https://github.com/levithion/NCF-Based-Movie-Recommender-System\" target=\"_blank\" rel=\"noreferrer\">Browse source code ↗</a>\n            </div>\n            \n            <a href=\"index.html#projects\" class=\"back-link\">Return to portfolio <span>→</span></a>\n        </article>\n    </main>\n    <footer class=\"article-footer\"><span>© 2026 Shshank Singh</span><span>Project documentation</span></footer>\n</body>\n</html>\n","type":"text/html; charset=utf-8","encoding":"text"},"/article-thalassa.html":{"body":"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Thalassa - AI Mental Health Chatbot | Shshank Singh</title>\n    \n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n    <link href=\"https://fonts.googleapis.com/css2?family=Lato:ital,wght@0,300;0,400;0,700;1,400&amp;display=swap\" rel=\"stylesheet\">\n    <link rel=\"stylesheet\" href=\"academic.css\">\n    <link rel=\"stylesheet\" href=\"article.css\">\n</head>\n<body class=\"article-page\">\n    <nav class=\"article-nav\">\n        <a class=\"article-brand\" href=\"index.html\"><span class=\"article-brand-mark\">SS</span><span class=\"article-brand-name\">Shshank Singh</span></a>\n        <a class=\"article-back\" href=\"index.html#projects\">← All work</a>\n    </nav>\n    <main class=\"article-shell\">\n        <div class=\"article-header\">\n            <p class=\"article-kicker\">Project 07 / Conversational AI</p>\n            <h1 class=\"article-title\">Thalassa - AI Mental Health Chatbot</h1>\n            <p class=\"article-date\">Sep 2024 — Oct 2024</p>\n        </div>\n        <article class=\"article-content\">\n            <div class=\"article-summary\">\n                <p>A full-stack wellness application combining authenticated LLM chat, persisted conversation history, mood records, private journal entries, and a curated resource library.</p>\n                <div class=\"article-facts\">\n                    <div><strong>LLaMA 3.1 8B</strong><span>Groq-hosted model</span></div>\n                    <div><strong>Last 10 messages</strong><span>Conversation context</span></div>\n                    <div><strong>5 data models</strong><span>SQLAlchemy persistence</span></div>\n                </div>\n            </div>\n\n            <h2>Problem and responsibility</h2>\n            <p>Thalassa began as an exploration of stateful conversational interfaces. A useful wellness application needs more than a single prompt box: people need authentication, continuity, a private place to write, and a way to see patterns over time.</p>\n            <p>The project is explicitly an AI demonstration, not therapy, diagnosis, or crisis care. That boundary matters because empathetic language can make a system appear more capable and authoritative than it is. The application therefore combines supportive prompt guidance with a resource library and a visible disclaimer.</p>\n\n            <h2>Application architecture</h2>\n            <p>The backend is a Flask application with CORS, SQLAlchemy, Flask-JWT-Extended, and separate blueprints for users, moods, resources, and journals. The frontend consists of HTML/CSS and JavaScript views for login, registration, chat, journaling, mood tracking, and resources.</p>\n            <ul>\n                <li><strong>User:</strong> stores credentials and owns all private records.</li>\n                <li><strong>ChatMessage:</strong> persists user and assistant messages with roles and timestamps.</li>\n                <li><strong>Mood:</strong> records a numeric or categorical emotional state over time for visualization.</li>\n                <li><strong>JournalEntry:</strong> stores timestamped private writing associated with one authenticated user.</li>\n                <li><strong>Resource:</strong> contains seeded grounding, breathing, and educational material.</li>\n            </ul>\n\n            <div class=\"article-diagram\" role=\"img\" aria-label=\"Thalassa system flow from authenticated client through Flask orchestration and LLaMA to persistent memory\">\n                <div class=\"article-diagram-label\"><span>FIG 01 / APPLICATION FLOW</span><span>Stateful LLM system</span></div>\n                <div class=\"diagram-flow\">\n                    <div><small>CLIENT</small><strong>JWT Session</strong><span>private user context</span></div>\n                    <div><small>ORCHESTRATION</small><strong>Flask API</strong><span>prompt + policy</span></div>\n                    <div><small>INTELLIGENCE</small><strong>LLaMA 3.1</strong><span>Groq inference</span></div>\n                    <div><small>MEMORY</small><strong>SQLite</strong><span>journal + mood history</span></div>\n                </div>\n            </div>\n\n            <h2>Conversation flow</h2>\n            <p>The chat endpoint requires a valid JWT, resolves the current user, persists the incoming message, and loads the ten most recent messages in chronological order. It then prepends a system prompt that asks the model to be patient, validating, non-judgmental, and concise, with an instruction to encourage professional support when severe crisis language appears.</p>\n            <p>The message array is sent to <code>llama-3.1-8b-instant</code> through the Groq client with temperature 0.7 and a 1,024-token output limit. The assistant reply is stored before it is returned, so page reloads can recover the conversation history.</p>\n\n            <div class=\"code-sample\">\n                <div class=\"code-sample-header\"><span>app.py / context assembly</span><span>Authenticated LLM request</span></div>\n                <pre><code>recent = ChatMessage.query.filter_by(\n    user_id=user.id\n).order_by(\n    ChatMessage.timestamp.desc()\n).limit(10).all()\n\nmessages = [{\"role\": \"system\", \"content\": SYSTEM_PROMPT}]\nmessages.extend(\n    {\"role\": item.role, \"content\": item.content}\n    for item in reversed(recent)\n)</code></pre>\n            </div>\n\n            <h2>Journaling and mood data</h2>\n            <p>The journal blueprint supports authenticated creation and retrieval of entries, ordered by timestamp. The mood routes follow the same ownership model: records are linked to the JWT identity and returned as a personal history. Chart.js turns that history into a time-series view in the browser.</p>\n            <p>These features do not feed directly into the LLM prompt in the current implementation. Keeping that distinction clear prevents the portfolio from claiming a level of memory or personalization that the source does not yet implement.</p>\n\n            <h2>Security and privacy review</h2>\n            <p>JWT protection and per-user database relationships establish a useful baseline, but sensitive wellness data requires a much higher production standard. The development configuration falls back to a default JWT secret when an environment variable is missing; production must refuse startup instead. SQLite data is not encrypted at the application layer, and the project does not yet include audit logs, retention controls, export/deletion workflows, rate limiting, or a formal threat model.</p>\n\n            <div class=\"article-callout\">\n                <strong>Safety boundary</strong>\n                <p>Prompt instructions are not a clinical safety system. A production wellness product would need expert-reviewed crisis handling, deterministic escalation rules, abuse testing, regional resources, privacy review, and continuous monitoring.</p>\n            </div>\n\n            <h2>Interface and deployment</h2>\n            <p>The deployed PythonAnywhere application uses a calm, low-contrast visual system intended to reduce cognitive load. Authentication gates the private views, while AJAX requests carry the JWT to the API. Flask serves both the frontend templates and JSON endpoints, which keeps deployment simple for a compact full-stack project.</p>\n\n            <h2>Next steps</h2>\n            <p>A stronger architecture would add secure secret enforcement, password reset and account deletion, encrypted storage, structured safety classifiers outside the generative model, summarized long-term memory with explicit user control, and test coverage for authorization boundaries. Mood and journal signals should only influence chat after informed consent and clear privacy controls.</p>\n\n            <div class=\"article-links\">\n                <a href=\"https://levithin.pythonanywhere.com\" target=\"_blank\" rel=\"noreferrer\">Open live application ↗</a>\n                <a href=\"https://github.com/levithion/Depressed-Person-Chatbot\" target=\"_blank\" rel=\"noreferrer\">Browse source code ↗</a>\n            </div>\n            \n            <a href=\"index.html#projects\" class=\"back-link\">Return to portfolio <span>→</span></a>\n        </article>\n    </main>\n    <footer class=\"article-footer\"><span>© 2026 Shshank Singh</span><span>Project documentation</span></footer>\n</body>\n</html>\n","type":"text/html; charset=utf-8","encoding":"text"},"/article-torchforge.html":{"body":"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>TorchForge Research-to-PyTorch Pipeline | Shshank Singh</title>\n    <meta name=\"description\" content=\"How TorchForge extracts architecture evidence from research papers, generates guarded PyTorch modules, and validates them across CPU, CUDA, and Apple MPS.\">\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n    <link href=\"https://fonts.googleapis.com/css2?family=Lato:ital,wght@0,300;0,400;0,700;1,400&amp;display=swap\" rel=\"stylesheet\">\n    <link rel=\"stylesheet\" href=\"academic.css\">\n    <link rel=\"stylesheet\" href=\"article.css\">\n</head>\n<body class=\"article-page\">\n    <nav class=\"article-nav\">\n        <a class=\"article-brand\" href=\"index.html\"><span class=\"article-brand-mark\">SS</span><span class=\"article-brand-name\">Shshank Singh</span></a>\n        <a class=\"article-back\" href=\"index.html#projects\">← All work</a>\n    </nav>\n    <main class=\"article-shell\">\n        <div class=\"article-header\">\n            <p class=\"article-kicker\">Project 01 / Research engineering</p>\n            <h1 class=\"article-title\">TorchForge: From Research Paper to Proven PyTorch</h1>\n            <p class=\"article-date\">Jul 2026 — Aug 2026</p>\n        </div>\n        <article class=\"article-content\">\n            <div class=\"article-summary\">\n                <p>TorchForge is a local-first research engineering pipeline that converts transformer and NLP papers into structured architecture evidence, importable PyTorch modules, and durable validation reports — with certified BERT and GPT-2 reference paths.</p>\n                <div class=\"article-facts\">\n                    <div><strong>4 phases</strong><span>Extract, parse, compile, validate</span></div>\n                    <div><strong>2 profiles</strong><span>Certified BERT Base · GPT-2 Small</span></div>\n                    <div><strong>CPU · CUDA · MPS</strong><span>Portable runtime validation</span></div>\n                </div>\n            </div>\n\n            <h2>Problem and objective</h2>\n            <p>Implementing a model from a research paper is not a simple translation task. Architecture details are scattered across prose, equations, diagrams, tables, and appendices. A generated Python file can look plausible while silently omitting a connection, misreading a dimension, or failing as soon as gradients and realistic tensors are introduced.</p>\n            <p>TorchForge asks a stricter question: can a paper become an implementation whose assumptions, structure, source, and runtime evidence remain inspectable? The system keeps every phase explicit and writes durable artifacts so later stages consume recorded evidence instead of relying on hidden application state.</p>\n\n            <h2>Four-phase architecture</h2>\n            <ul>\n                <li><strong>Extract:</strong> PyMuPDF recovers text, metadata, embedded images, and high-resolution candidate figure pages, with optional Nougat OCR.</li>\n                <li><strong>Parse:</strong> certified architecture profiles or local Ollama vision models convert paper evidence into a Pydantic-validated topology graph.</li>\n                <li><strong>Compile:</strong> a deterministic reference compiler or local code model creates one device-agnostic <code>torch.nn.Module</code>, guarded by static AST checks.</li>\n                <li><strong>Validate:</strong> the pipeline instantiates the module, executes representative tensors, checks outputs and gradients, and can return runtime failures to the compiler for repair.</li>\n            </ul>\n\n            <div class=\"code-sample\">\n                <div class=\"code-sample-header\"><span>torchforge / durable contract</span><span>manifest.json</span></div>\n                <pre><code>paper.pdf\n  → extracted text + figures\n  → topology.json\n  → generated_model.py\n  → validation.json\n\nmanifest.json records every phase,\nartifact path, warning, and outcome.</code></pre>\n            </div>\n\n            <h2>Certified behavior and safety gates</h2>\n            <p>When the original BERT paper is identified unambiguously, TorchForge uses a certified BERT Base profile rather than asking a small vision model to reconstruct known details. The resulting topology includes 12 encoder layers, 12 attention heads, a 768-wide hidden state, a 3,072-wide intermediate layer, post-normalization residual blocks, attention masks, segment IDs, and the pooler.</p>\n            <p>The generated encoder is verified at 109,482,240 parameters. An optional reference suite maps identical weights into Hugging Face <code>BertModel</code> and TorchForge BERT, then compares masked and segmented forward outputs numerically.</p>\n            <p>The certified library now also includes GPT-2 Small: a 12-layer, 12-head decoder with causal attention, pre-normalization residual blocks, GELU’s tanh approximation, and 124,439,808 parameters. Its conformance suite checks Hugging Face parity and proves causality by changing the final token and confirming that earlier output positions do not move.</p>\n            <p>Unknown papers remain model interpretations. TorchForge validates graph IDs, endpoints, shapes, bounds, and assumptions; recalibrates confidence when evidence is incomplete; and blocks compilation below a 0.60 confidence threshold. That gate prevents “generated code” from being mistaken for a successful reconstruction.</p>\n\n            <div class=\"article-callout\">\n                <strong>Trust boundary</strong>\n                <p>Static AST checks reject several dangerous or invalid patterns, but generated Python is not a security sandbox. For untrusted architectures, <code>TORCHFORGE_SANDBOX=docker</code> runs validation with no network, a read-only filesystem, dropped capabilities, and bounded CPU and memory. When Docker is unavailable, the run falls back to the local process and records that warning.</p>\n            </div>\n\n            <h2>One engine, two interfaces</h2>\n            <p>The CLI supports single-paper extraction, directory watching, topology parsing, compilation, validation, and API serving. TorchForge Studio exposes the same engine in a browser workspace with multi-PDF queues, persisted jobs, Server-Sent Events progress, cancellation and retry, local-model health, device status, and artifact inspection.</p>\n            <p>Studio now supports editable topology graphs, a Monaco editor with static validation and revision diffs, PDF-and-figure evidence side by side, cross-run comparison, and exports for artifact bundles, model cards, source, generated code, ONNX, and TorchScript. The backend is built with FastAPI, PyTorch, Pydantic, and PyMuPDF; Studio uses Next.js, React, and TypeScript.</p>\n\n            <h2>Validation evidence, not just a passing shape</h2>\n            <p>Runtime validation selects CUDA first, then Apple MPS, then CPU, and records representative input/output shapes, finite values, gradient flow, tracebacks, and repair history. Each report also includes forward-pass mean, p50, and p95 latency, throughput, peak memory, and estimated FLOPs from <code>torch.profiler</code>.</p>\n            <p>TorchForge separates schema-valid, statically valid, runtime-valid, structurally conformant, and reference-verified outcomes. A model that merely returns a tensor is not presented as faithful to a paper; the strongest claims are reserved for certified profiles and their explicit conformance checks.</p>\n\n            <h2>Outcome and next steps</h2>\n            <p>TorchForge turns research reproduction into an auditable compilation pipeline. Its strongest result is not merely code generation; it is the chain of evidence between the paper, the extracted topology, the guarded source, and the runtime report.</p>\n            <p>Current support is deepest for certified BERT Base and GPT-2 Small behavior. Other transformer and NLP papers rely on local vision interpretation and code generation, so their outputs remain bounded by evidence quality, model context, and the safety gate. Expanding the certified architecture library and adding more conformance profiles are the clearest next steps.</p>\n\n            <div class=\"article-links\">\n                <a href=\"https://github.com/levithion/TorchForge\" target=\"_blank\" rel=\"noreferrer\">Browse source code ↗</a>\n            </div>\n            <a href=\"index.html#projects\" class=\"back-link\">Return to portfolio <span>→</span></a>\n        </article>\n    </main>\n    <footer class=\"article-footer\"><span>© 2026 Shshank Singh</span><span>Project documentation</span></footer>\n</body>\n</html>\n","type":"text/html; charset=utf-8","encoding":"text"},"/article.css":{"body":"/* Case-study pages: light academic theme, builds on academic.css */\n\n.article-page { --code-bg: #f6f7f9; }\n\n.article-nav {\n    display: flex;\n    flex-wrap: wrap;\n    align-items: baseline;\n    justify-content: space-between;\n    gap: 8px 24px;\n    max-width: 820px;\n    margin: 0 auto;\n    padding: 22px 20px 14px;\n    border-bottom: 1px solid var(--rule);\n}\n\n.article-brand { color: var(--text); font-size: 1.05rem; font-weight: 700; }\n.article-brand:hover { color: var(--link); text-decoration: none; }\n.article-brand-mark { display: none; }\n.article-back { font-size: 0.95rem; }\n\n.article-shell { max-width: 820px; margin: 0 auto; padding: 0 20px 24px; }\n\n.article-header { padding: 34px 0 8px; }\n.article-kicker { margin: 0 0 6px; color: var(--muted); font-size: 0.9rem; }\n.article-title { margin: 0 0 8px; font-size: 1.9rem; font-weight: 400; line-height: 1.25; }\n.article-date { margin: 0; color: var(--muted); font-size: 0.95rem; }\n\n.article-summary { margin: 18px 0 8px; padding: 14px 0; border-top: 1px solid var(--rule); border-bottom: 1px solid var(--rule); }\n.article-summary > p { margin: 0 0 12px; }\n.article-facts { display: grid; grid-template-columns: repeat(auto-fit, minmax(170px, 1fr)); gap: 10px 20px; }\n.article-facts strong { display: block; font-size: 0.98rem; }\n.article-facts span { color: var(--muted); font-size: 0.88rem; }\n\n.article-content h2 {\n    margin: 32px 0 10px;\n    padding-bottom: 5px;\n    border-bottom: 1px solid var(--rule);\n    font-size: 1.3rem;\n    font-weight: 700;\n}\n.article-content h3 { margin: 22px 0 6px; font-size: 1.05rem; font-weight: 700; }\n.article-content p { margin: 0 0 12px; }\n.article-content ul, .article-content ol { margin: 0 0 14px; padding-left: 22px; }\n.article-content li { margin-bottom: 6px; }\n\ncode, pre { font-family: ui-monospace, \"SF Mono\", Menlo, Consolas, monospace; }\n:not(pre) > code {\n    padding: 1px 5px;\n    border-radius: 3px;\n    background: var(--code-bg);\n    font-size: 0.88em;\n}\n\n.code-sample { margin: 18px 0; border: 1px solid var(--rule); border-radius: 4px; overflow: hidden; }\n.code-sample-header,\n.article-diagram-label,\n.article-figure figcaption {\n    display: flex;\n    flex-wrap: wrap;\n    justify-content: space-between;\n    gap: 2px 16px;\n    padding: 7px 12px;\n    background: var(--code-bg);\n    color: var(--muted);\n    font-size: 0.82rem;\n}\n.code-sample-header { border-bottom: 1px solid var(--rule); }\n.code-sample pre { margin: 0; padding: 12px; overflow-x: auto; font-size: 0.85rem; line-height: 1.5; }\n\n.article-callout { margin: 20px 0; padding: 10px 16px; border-left: 3px solid var(--link); background: var(--code-bg); }\n.article-callout strong { display: block; margin-bottom: 4px; }\n.article-callout p { margin: 0; }\n\n/* Diagrams and figures */\n.article-diagram,\n.article-figure { margin: 20px 0; border: 1px solid var(--rule); border-radius: 4px; overflow: hidden; }\n.article-diagram-label { border-bottom: 1px solid var(--rule); }\n\n.diagram-flow,\n.model-flow {\n    display: grid;\n    grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));\n    gap: 10px;\n    padding: 14px;\n}\n\n.diagram-flow > div,\n.model-flow > div {\n    padding: 10px 12px;\n    border: 1px solid var(--rule);\n    border-radius: 4px;\n    background: #fff;\n}\n.model-flow > .model-stage,\n.model-flow > .output-stage { border-color: var(--link); }\n\n.diagram-flow small,\n.model-flow small { display: block; color: var(--muted); font-size: 0.72rem; letter-spacing: 0.05em; }\n.diagram-flow strong,\n.model-flow strong { display: block; font-size: 0.95rem; }\n.diagram-flow span,\n.model-flow span { color: var(--muted); font-size: 0.82rem; }\n\n.model-readout {\n    display: flex;\n    flex-wrap: wrap;\n    gap: 4px 20px;\n    padding: 8px 14px;\n    border-top: 1px solid var(--rule);\n    background: var(--code-bg);\n    color: var(--muted);\n    font-size: 0.78rem;\n}\n\n.article-figure { margin-left: 0; margin-right: 0; }\n.article-figure img { display: block; width: 100%; height: auto; }\n.article-figure figcaption { border-top: 1px solid var(--rule); }\n\n.article-links { margin: 22px 0 8px; }\n.back-link { display: inline-block; margin-top: 8px; }\n\n.article-footer {\n    display: flex;\n    flex-wrap: wrap;\n    justify-content: space-between;\n    gap: 6px 20px;\n    max-width: 780px;\n    margin: 30px auto 0;\n    padding: 16px 0 40px;\n    border-top: 1px solid var(--rule);\n    color: var(--muted);\n    font-size: 0.88rem;\n}\n\n@media (max-width: 640px) {\n    .article-figure { overflow-x: auto; -webkit-overflow-scrolling: touch; }\n    .article-figure img { width: 560px; max-width: none; height: auto; }\n    .article-figure img[src*=\"pipeline\"] { width: 920px; }\n    .article-figure figcaption { position: sticky; left: 0; }\n    .article-title { font-size: 1.55rem; }\n    .article-footer { margin-left: 20px; margin-right: 20px; }\n}\n","type":"text/css; charset=utf-8","encoding":"text"},"/assets/portfolio-og.jpg":{"body":"","type":"image/jpeg","encoding":"base64"},"/assets/profile.jpg":{"body":"","type":"image/jpeg","encoding":"base64"},"/assets/projects/huffman-compression.png":{"body":"","type":"image/png","encoding":"base64"},"/assets/projects/huffman-pipeline.png":{"body":"","type":"image/png","encoding":"base64"},"/index.html":{"body":"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Shshank Singh</title>\n    <meta name=\"description\" content=\"Shshank Singh is an AI/ML and software engineer building reliable machine-learning systems, APIs, retrieval products, and developer tools.\">\n    <meta property=\"og:title\" content=\"Shshank Singh — AI/ML &amp; Software Engineer\">\n    <meta property=\"og:description\" content=\"AI/ML and software systems engineered beyond the prototype.\">\n    <meta property=\"og:type\" content=\"website\">\n    <meta property=\"og:image\" content=\"https://levithion.github.io/assets/portfolio-og.jpg\">\n    <meta name=\"twitter:card\" content=\"summary_large_image\">\n    <meta name=\"twitter:title\" content=\"Shshank Singh — AI/ML &amp; Software Engineer\">\n    <meta name=\"twitter:description\" content=\"AI/ML and software systems engineered beyond the prototype.\">\n    <meta name=\"twitter:image\" content=\"https://levithion.github.io/assets/portfolio-og.jpg\">\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n    <link href=\"https://fonts.googleapis.com/css2?family=Lato:ital,wght@0,300;0,400;0,700;1,400&amp;display=swap\" rel=\"stylesheet\">\n    <link rel=\"stylesheet\" href=\"academic.css\">\n</head>\n<body>\n    <a class=\"skip-link\" href=\"#about\">Skip to content</a>\n    <div class=\"page\">\n        <header class=\"topbar\">\n            <a class=\"name\" href=\"#top\" id=\"top\">Shshank Singh</a>\n            <nav aria-label=\"Primary navigation\">\n                <a href=\"#about\">About</a>\n                <a href=\"#projects\">Projects</a>\n                <a href=\"#experience\">Experience</a>\n                <a href=\"#skills\">Skills</a>\n                <a href=\"https://drive.google.com/uc?export=download&amp;id=1AzV5i674KrVEoc3fdeQ31OjtPUZJtxIm\" target=\"_blank\" rel=\"noreferrer\">Résumé</a>\n            </nav>\n        </header>\n\n        <main>\n            <section class=\"intro\" id=\"about\">\n                <div class=\"intro-text\">\n                    <h1>Shshank Singh</h1>\n                    <p>I’m an AI/ML and software engineer from India. I build machine-learning systems that work beyond the prototype: reliable APIs, retrieval and recommendation products, and the developer tools and interfaces around them. I’m currently open to AI/ML Engineer, ML Engineer, and Software Engineer roles.</p>\n                    <p>My work spans ML systems, backend services, semantic retrieval, personalization, computer vision, and LLM applications. I like to build end to end: understand the mechanism, define the contract, test the failure modes, measure the result, then ship the useful part. In summer 2025 I was a Software / ML intern at the Indian Institute of Technology (BHU), Varanasi. I also practice data structures and algorithms on <a href=\"https://takeuforward.org/profile/levi7kai\" target=\"_blank\" rel=\"noreferrer\">TakeUForward</a>.</p>\n                    <p class=\"linkline\">\n                        <a href=\"https://drive.google.com/uc?export=download&amp;id=1AzV5i674KrVEoc3fdeQ31OjtPUZJtxIm\" target=\"_blank\" rel=\"noreferrer\">Résumé</a><span class=\"sep\">/</span><a href=\"https://github.com/levithion\" target=\"_blank\" rel=\"noreferrer\">GitHub</a><span class=\"sep\">/</span><a href=\"https://www.linkedin.com/in/shshank-singh-levithion/\" target=\"_blank\" rel=\"noreferrer\">LinkedIn</a><span class=\"sep\">/</span><a href=\"https://takeuforward.org/profile/levi7kai\" target=\"_blank\" rel=\"noreferrer\">TakeUForward</a>\n                    </p>\n                </div>\n                <div class=\"photo\"><img src=\"assets/profile.jpg\" alt=\"Portrait of Shshank Singh\" width=\"165\" height=\"220\"></div>\n            </section>\n\n            <section id=\"projects\" aria-labelledby=\"projects-title\">\n                <h2 id=\"projects-title\">Selected Projects</h2>\n                <p class=\"section-note\">Each project has a technical case study covering the data, model, API, validation evidence, and trade-offs.</p>\n\n                <article class=\"paper\">\n                    <div>\n                        <h3><a href=\"article-torchforge.html\">TorchForge: From Transformer Papers to Reference-Verified PyTorch Modules</a></h3>\n                        <p class=\"tech\">PyTorch, FastAPI, Ollama, PyMuPDF, Docker, Next.js · 2026</p>\n                        <p>A local-first compiler pipeline that extracts paper evidence into a validated topology, compiles guarded code, and verifies behavior across CPU, CUDA, or MPS. Four explicit phases and certified BERT and GPT-2 profiles make each run traceable from PDF to report.</p>\n                        <p class=\"links\"><a href=\"article-torchforge.html\">case study</a><span class=\"sep\">|</span><a href=\"https://github.com/levithion/TorchForge\" target=\"_blank\" rel=\"noreferrer\">code</a></p>\n                    </div>\n                </article>\n\n                <article class=\"paper\">\n                    <div>\n                        <h3><a href=\"article-lumina.html\">Lumina: Local-First Multimodal Memory Search</a></h3>\n                        <p class=\"tech\">SmolVLM, CLIP, MiniLM, Qdrant, FastAPI, pywebview · 2026</p>\n                        <p>Private screenshot search by meaning, on-screen text, and time, entirely on-device. A single process captions each capture, stores dual 512D and 384D vectors in embedded Qdrant, and fuses three signals for retrieval, taking roughly ten seconds from screenshot to searchable.</p>\n                        <p class=\"links\"><a href=\"article-lumina.html\">case study</a><span class=\"sep\">|</span><a href=\"https://github.com/levithion/Lumina\" target=\"_blank\" rel=\"noreferrer\">code</a></p>\n                    </div>\n                </article>\n\n                <article class=\"paper\">\n                    <div>\n                        <h3><a href=\"article-ncf-recommender.html\">CineMatch: Neural Collaborative Filtering Movie Recommender</a></h3>\n                        <p class=\"tech\">PyTorch, TF-IDF, FastAPI, Streamlit, SQLite · 2025</p>\n                        <p>Turns a PyTorch NCF model trained on 100K ratings, 9K movies, and 600 users into a personalized discovery product. A hybrid ranker blends NCF scores with TF-IDF title and genre similarity and popularity, behind a FastAPI backend with accounts, watchlists, and cold-start handling.</p>\n                        <p class=\"links\"><a href=\"article-ncf-recommender.html\">case study</a><span class=\"sep\">|</span><a href=\"https://ncf-based-movie-recommender-system.streamlit.app\" target=\"_blank\" rel=\"noreferrer\">demo</a><span class=\"sep\">|</span><a href=\"https://github.com/levithion/NCF-Based-Movie-Recommender-System\" target=\"_blank\" rel=\"noreferrer\">code</a></p>\n                    </div>\n                </article>\n\n                <article class=\"paper\">\n                    <div>\n                        <h3><a href=\"article-huffman.html\">Context-Aware Huffman Coding with N-order Markov Models</a></h3>\n                        <p class=\"tech\">Python, Markov models, entropy coding · 2025</p>\n                        <p>Extends classic Huffman coding with context-specific trees, memory-aware pruning, and entropy benchmarks. Achieves a 15–20% compression improvement, saving about 1.2 bits per token across four datasets.</p>\n                        <p class=\"links\"><a href=\"article-huffman.html\">case study</a><span class=\"sep\">|</span><a href=\"https://github.com/levithion/Context-Aware-Huffman\" target=\"_blank\" rel=\"noreferrer\">code</a></p>\n                    </div>\n                </article>\n\n                <article class=\"paper\">\n                    <div>\n                        <h3><a href=\"article-drowsiness.html\">Driver Drowsiness Detection with Edge-Optimized CNNs</a></h3>\n                        <p class=\"tech\">Keras, MobileNetV2, Streamlit, WebRTC</p>\n                        <p>CNN inference for detecting micro-sleep indicators under changing light, trained on 41,793 images with a rolling score over a 224px two-class output.</p>\n                        <p class=\"links\"><a href=\"article-drowsiness.html\">case study</a><span class=\"sep\">|</span><a href=\"https://github.com/levithion/Driver-Drowsiness-Detection\" target=\"_blank\" rel=\"noreferrer\">code</a></p>\n                    </div>\n                </article>\n\n                <article class=\"paper\">\n                    <div>\n                        <h3><a href=\"article-book-recommender.html\">Book Discovery Engine: Natural-Language Retrieval with Sentence Embeddings</a></h3>\n                        <p class=\"tech\">Sentence Transformers, MiniLM, scikit-learn, Streamlit</p>\n                        <p>Retrieves books from natural-language queries over 5.2K+ cleaned descriptions using dense MiniLM embeddings and cosine similarity.</p>\n                        <p class=\"links\"><a href=\"article-book-recommender.html\">case study</a><span class=\"sep\">|</span><a href=\"https://query-based-book-recommender-system.streamlit.app\" target=\"_blank\" rel=\"noreferrer\">demo</a><span class=\"sep\">|</span><a href=\"https://github.com/levithion/Query-Based-Book-Recommender-System-Using-Sentence-Transformers\" target=\"_blank\" rel=\"noreferrer\">code</a></p>\n                    </div>\n                </article>\n\n                <article class=\"paper\">\n                    <div>\n                        <h3><a href=\"article-thalassa.html\">Thalassa: A Stateful AI Companion with Private Journaling and Mood Analytics</a></h3>\n                        <p class=\"tech\">LLaMA 3.1 (Groq), Flask, JWT, SQLAlchemy, SQLite</p>\n                        <p>A conversational system with JWT-secured accounts, SQLite-backed memory, private journaling, and a 7-day mood trend dashboard.</p>\n                        <p class=\"links\"><a href=\"article-thalassa.html\">case study</a><span class=\"sep\">|</span><a href=\"https://github.com/levithion/Depressed-Person-Chatbot\" target=\"_blank\" rel=\"noreferrer\">code</a></p>\n                    </div>\n                </article>\n            </section>\n\n            <section id=\"experience\" aria-labelledby=\"experience-title\">\n                <h2 id=\"experience-title\">Experience</h2>\n                <ul class=\"entries\">\n                    <li>\n                        <span class=\"when\">May – Jul 2025</span>\n                        <div>\n                            <strong>Software / ML Intern</strong>, Indian Institute of Technology (BHU), Varanasi<br>\n                            Built and integrated a hybrid recommendation system from data preparation and model design to API inference, persistence, and an interactive product surface.\n                        </div>\n                    </li>\n                </ul>\n            </section>\n\n            <section id=\"skills\" aria-labelledby=\"skills-title\">\n                <h2 id=\"skills-title\">Skills</h2>\n                <dl class=\"skills\">\n                    <dt>Languages</dt><dd>Python, C++, JavaScript, SQL</dd>\n                    <dt>ML</dt><dd>PyTorch, TensorFlow, Scikit-learn, CLIP, LLMs, Ollama</dd>\n                    <dt>Retrieval</dt><dd>Qdrant, embeddings, RAG</dd>\n                    <dt>Backend</dt><dd>FastAPI, Flask, Django, REST</dd>\n                    <dt>Data</dt><dd>SQL, SQLite, Firebase, NumPy</dd>\n                    <dt>Tools</dt><dd>Git, Linux, Docker, Streamlit, Plotly, HTML/CSS</dd>\n                    <dt>Coding</dt><dd><a href=\"https://takeuforward.org/profile/levi7kai\" target=\"_blank\" rel=\"noreferrer\">TakeUForward profile</a></dd>\n                </dl>\n            </section>\n        </main>\n\n        <footer>\n            <span>© 2026 Shshank Singh</span>\n            <a href=\"#top\">Back to top ↑</a>\n        </footer>\n    </div>\n</body>\n</html>\n","type":"text/html; charset=utf-8","encoding":"text"}};

export default {
  async fetch(request) {
    const url = new URL(request.url);
    let pathname = decodeURIComponent(url.pathname);

    if (pathname === "/") pathname = "/index.html";
    if (!pathname.includes(".") && assets[`${pathname}.html`]) {
      pathname = `${pathname}.html`;
    }

    const asset = assets[pathname];

    if (!asset) {
      return new Response("Not found", {
        status: 404,
        headers: { "content-type": "text/plain; charset=utf-8" }
      });
    }

    const body = asset.encoding === "base64"
      ? Uint8Array.from(atob(asset.body), character => character.charCodeAt(0))
      : asset.body;

    return new Response(request.method === "HEAD" ? null : body, {
      headers: {
        "content-type": asset.type,
        "cache-control": asset.type.startsWith("text/html")
          ? "public, max-age=0, must-revalidate"
          : "public, max-age=3600"
      }
    });
  }
};
